var t=`0395-yorkshire-pudding`;var n=`world-0395`;var o=`GB`;var r=`northern-europe`;var l=4;var a=63;var d={en:`Yorkshire Pudding`,ua:`Йоркширський пудинг`};var s={en:`A traditional United Kingdom dish made with all-purpose flour, chicken egg, whole cow milk. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Велика Британія. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,195,`g`],[`chicken-egg`,4,`pcs`],[`whole-cow-milk`,300,`ml`],[`table-salt`,4,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 30 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 30 хвилин.`,t:[`rapid-chilling`],m:30,i:[]},{en:`Preheat the dripping in the muffin tin until smoking hot, pour in the cold batter, and bake at 220°C without opening the oven until dramatically puffed and deep golden.`,ua:`Розігрійте жир у формах до дуже гарячого стану, влийте холодне тісто й випікайте при 220°C, не відчиняючи духовку, доки пудинги сильно піднімуться й зарум’яняться.`,t:[`high-temperature-roasting`,`baking`],m:24,i:[[`duck-fat`,90,`g`]]}];var g={slug:t,id:n,country:`GB`,region:r,servings:4,minutes:63,title:d,text:s,steps:u};export{o as country,g as default,n as id,a as minutes,r as region,l as servings,t as slug,u as steps,s as text,d as title};